CREATE TABLE organizations (id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE projects (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE users (id uuid PRIMARY KEY, username text NOT NULL UNIQUE, display_name text NOT NULL, organization_id uuid NOT NULL REFERENCES organizations(id), team text NOT NULL);
CREATE TABLE environments (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), name text NOT NULL CHECK (name IN ('development','staging','production')), revision integer NOT NULL CHECK (revision >= 0), updated_at timestamptz NOT NULL, UNIQUE(project_id,name));
CREATE TABLE role_assignments (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), project_id uuid NOT NULL REFERENCES projects(id), role text NOT NULL CHECK (role IN ('member','developer','operator','change_approver','org_admin','auditor')), active boolean NOT NULL, updated_at timestamptz NOT NULL);
CREATE INDEX role_subject_scope ON role_assignments(user_id,project_id,role,active);
CREATE TABLE access_requests (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), requester_id uuid NOT NULL REFERENCES users(id), target_user_id uuid NOT NULL REFERENCES users(id), requested_role text NOT NULL, status text NOT NULL CHECK (status IN ('DRAFT','PENDING','APPROVED','REJECTED','APPLIED','REVOKED')), approver_id uuid REFERENCES users(id), revision integer NOT NULL CHECK (revision > 0), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE changes (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), environment_id uuid NOT NULL REFERENCES environments(id), requester_id uuid NOT NULL REFERENCES users(id), status text NOT NULL CHECK (status IN ('DRAFT','READY','PENDING_APPROVAL','APPROVED','QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED','EXPIRED','SUPERSEDED')), approver_id uuid REFERENCES users(id), revision integer NOT NULL CHECK (revision > 0), summary text NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE jobs (id uuid PRIMARY KEY, change_id uuid NOT NULL REFERENCES changes(id), environment_id uuid NOT NULL REFERENCES environments(id), initiator_id uuid NOT NULL REFERENCES users(id), status text NOT NULL CHECK (status IN ('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED')), queued_tick integer NOT NULL, due_tick integer NOT NULL, started_tick integer, finished_tick integer, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE INDEX jobs_due ON jobs(status,due_tick,id);
CREATE TABLE logical_clock (singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton), tick integer NOT NULL, origin timestamptz NOT NULL);
CREATE TABLE audit_events (sequence bigserial PRIMARY KEY, tick integer NOT NULL, actor_id uuid REFERENCES users(id), executor text NOT NULL, action text NOT NULL, object_id uuid NOT NULL, project_id uuid REFERENCES projects(id), status text NOT NULL, created_at timestamptz NOT NULL);
